func gabungTerurut(a []int, b []int) []int {
	hasil := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			hasil = append(hasil, a[i])
			i++
		} else {
			hasil = append(hasil, b[j])
			j++
		}
	}
	hasil = append(hasil, a[i:]...)
	hasil = append(hasil, b[j:]...)
	return hasil
}
